const upsertUserSettings = `-- name: UpsertUserSettings :one
INSERT INTO dayorder.user_settings (user_id, schema_version, version, settings)
VALUES ($1, $2, 1, $3)
ON CONFLICT (user_id) DO UPDATE
SET schema_version = EXCLUDED.schema_version,
    settings = EXCLUDED.settings,
    version = dayorder.user_settings.version + 1,
    updated_at = now()
WHERE dayorder.user_settings.version = $4
RETURNING user_id, schema_version, version, settings, updated_at
`

func (q *Queries) UpsertUserSettings(ctx context.Context, userID pgtype.UUID, schemaVersion int32, settings []byte, expectedVersion int64) (*DayorderUserSetting, error) {
	row := q.db.QueryRow(ctx, upsertUserSettings,
		userID,
		schemaVersion,
		settings,
		expectedVersion,
	)
	var i DayorderUserSetting
	err := row.Scan(
		&i.UserID,
		&i.SchemaVersion,
		&i.Version,
		&i.Settings,
		&i.UpdatedAt,
	)
	return &i, err
}
